import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("documents from another tenant are invisible", { tag: "@DOC-07" }, async ({ apiAs }) => {
    // Arrange: a document owned by the Globex tenant
    const globex = await apiAs("otherTenant");
    const globexVendor = await globex.post("/api/vendors", {
      data: {
        name: uniqueName("Globex Vendor"),
        category: "services",
        contact_email: "billing@globex-vendor.com",
      },
    });
    expect(globexVendor.status(), await globexVendor.text()).toBe(201);
    const vendorId = ((await globexVendor.json()) as { id: string }).id;

    const upload = await globex.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9.pdf",
          mimeType: "application/pdf",
          buffer: Buffer.from("%PDF-1.4\n%%EOF\n"),
        },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
    const documentId = ((await upload.json()) as { id: string }).id;

    // Arrange: a draft vendor for the Northwind member (background)
    const member = await apiAs("member");
    const ownVendor = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Northwind Vendor"),
        category: "hardware",
        contact_email: "ap@northwind-vendor.com",
      },
    });
    expect(ownVendor.status(), await ownVendor.text()).toBe(201);
    expect(((await ownVendor.json()) as { status: string }).status).toBe("draft");

    // Act
    const response = await member.get(`/api/documents/${documentId}`);

    // Assert
    expect(response.status(), await response.text()).toBe(404);
    const body = (await response.json()) as { error: { code: string } };
    expect(body.error.code, JSON.stringify(body)).toBe("document_not_found");
  });
});
